// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { compactTerm, termCode } from "../../../main/frontend/graph-explorer/graph-terms.ts";

test("a term's code line: the IRI, a literal's language or datatype, or that it is a blank node", () => {
  assert.equal(termCode({ id: "http://schema.org/name", label: "name", kind: "iri" }), "schema:name");
  assert.equal(termCode({ id: "x", label: "Hallo", kind: "literal", language: "de" }), "@de");
  assert.equal(
    termCode({ id: "x", label: "39", kind: "literal", datatype: "http://www.w3.org/2001/XMLSchema#integer" }),
    "xsd:integer",
  );
  assert.equal(termCode({ id: "x", label: "plain", kind: "literal" }), "xsd:string");
  assert.equal(termCode({ id: "__rdf_bnode__:b1", label: "address of Bob", kind: "blank" }), "blank node");
  assert.equal(termCode(undefined, "http://example.org/unknown"), compactTerm("http://example.org/unknown", 42));
});
